-- ============================================================================
-- 05_migracion_datos.sql  |  Datos historicos del Excel (generado por el ETL)
-- Ejecutar DESPUES de 04_catalogos.sql. Las personas estan seudonimizadas.
-- ============================================================================
SET search_path TO paros, public;




-- Reiniciar las secuencias de identidad (PostgreSQL) para que los nuevos INSERT continuen la numeracion
SELECT setval(pg_get_serial_sequence('registro_produccion', 'id_registro'), (SELECT MAX(id_registro) FROM registro_produccion));
SELECT setval(pg_get_serial_sequence('paro', 'id_paro'), (SELECT MAX(id_paro) FROM paro));
SELECT setval(pg_get_serial_sequence('parada_maquina', 'id_parada'), (SELECT MAX(id_parada) FROM parada_maquina));
SELECT setval(pg_get_serial_sequence('persona', 'id_persona'), (SELECT MAX(id_persona) FROM persona));
SELECT setval(pg_get_serial_sequence('referencia', 'id_referencia'), (SELECT MAX(id_referencia) FROM referencia));
SELECT setval(pg_get_serial_sequence('subcodigo_paro', 'id_subcodigo'), (SELECT MAX(id_subcodigo) FROM subcodigo_paro));
SELECT setval(pg_get_serial_sequence('motivo_parada', 'id_motivo'), (SELECT MAX(id_motivo) FROM motivo_parada));
SELECT setval(pg_get_serial_sequence('maquina', 'id_maquina'), (SELECT MAX(id_maquina) FROM maquina));
SELECT setval(pg_get_serial_sequence('turno', 'id_turno'), (SELECT MAX(id_turno) FROM turno));
SELECT setval(pg_get_serial_sequence('area_impacto', 'id_area'), (SELECT MAX(id_area) FROM area_impacto));
